/**
 * Test Flow: forEach Data Pill Type Annotation Replacement
 *
 * This flow tests the fix for the bug where datapills with type annotations inside forEach loops
 * were not being replaced with UUID-based references.
 *
 * Bug Scenario:
 * - wfa.dataPill(user, 'reference') generated `{{forEach.user|reference}}`
 * - Expected: `{{UUID.item|reference}}` where UUID is the forEach instance's ui_id
 *
 * Root Cause:
 * - The regex pattern in updateRecordsWithDataPills only matched `([.}])` after the parameter name
 * - It didn't account for `|` (pipe) character used in type annotations
 *
 * Fix:
 * - Updated regex from `([.}])` to `([.}|])` to include pipe character
 * - Location: packages/build-plugins/src/flow/flow-logic/flow-logic-plugin.ts:320
 */

import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['weekly_deactivate_inactive_users'],
        name: 'Weekly Deactivate Inactive Users',
    },
    wfa.trigger(
        trigger.scheduled.weekly,
        { $id: Now.ID['sunday_2am_trigger'] },
        {
            day_of_week: 1,
            time: Time({ hours: 2, minutes: 0, seconds: 0 }, 'UTC'),
        }
    ),
    (_params) => {
        const inactiveUsers = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_inactive_users'],
                annotation: 'Find active users who have not logged in for 90 days',
            },
            {
                table: 'sys_user',
                conditions: 'active=true^last_login_time<javascript:gs.daysAgoStart(90)^last_login_timeISNOTEMPTY',
                max_results: 500,
                sort_column: 'last_login_time',
                sort_type: 'sort_asc',
            }
        )

        // Test forEach with type-annotated datapills
        wfa.flowLogic.forEach(
            wfa.dataPill(inactiveUsers.Records, 'array.object'),
            {
                $id: Now.ID['process_each_user'],
                annotation: 'Deactivate each user and send notification',
            },
            (user) => {
                // Test Case 1: Direct parameter reference with type annotation
                // Before fix: {{forEach.user|reference}} ❌
                // After fix:  {{UUID.item|reference}} ✅
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['deactivate_user'],
                        annotation: 'Set user active status to false',
                    },
                    {
                        table_name: 'sys_user',
                        record: wfa.dataPill(user, 'reference'), // ← Critical test: direct parameter with type
                        values: TemplateValue({
                            active: 'false',
                        }),
                    }
                )

                // Test Case 2: Property access with type annotation
                // Before fix: {{forEach.user.email|string}} (worked because of the `.` after user)
                // After fix:  {{UUID.item.email|string}} ✅
                wfa.action(
                    action.core.sendEmail,
                    {
                        $id: Now.ID['send_deactivation_email'],
                        annotation: 'Notify user about account deactivation',
                    },
                    {
                        ah_to: wfa.dataPill(user.email, 'string'), // ← Property access with type
                        ah_subject: `Your ServiceNow Account Has Been Deactivated Due to Inactivity`,
                        ah_body:
                            '<h2>Account Deactivation Notice</h2><p>Your ServiceNow account has been deactivated because no login activity was detected in the last 90 days.</p><p>If you believe this is an error or you need your account reactivated, please contact your IT administrator.</p>',
                        watermark_email: false,
                    }
                )
            }
        )
    }
)
